import{_ as o,o as t,c as a,ag as i}from"./chunks/framework.8tqBsFWt.js";const m=JSON.parse('{"title":"Deploying VERA","description":"","frontmatter":{},"headers":[],"relativePath":"operations/deploy.md","filePath":"operations/deploy.md"}'),s={name:"operations/deploy.md"};function n(r,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="deploying-vera" tabindex="-1">Deploying VERA <a class="header-anchor" href="#deploying-vera" aria-label="Permalink to &quot;Deploying VERA&quot;">​</a></h1><p>VERA runs in two places on Railway:</p><ul><li><strong>Staging</strong>, at <code>https://vera-staging-staging-7e23.up.railway.app</code>, follows <code>main</code>. Every merge to <code>main</code> deploys there once CI passes. It has its own database and a Slack-less test tenant, and it never sends email, posts to Slack or files GitHub issues. With <code>DEMO_TENANT_ID</code> set to that tenant&#39;s id, it is reseeded with demo data every weekday morning and from <strong>Reseed demo data</strong> in <code>/admin</code> (see <a href="/operations/demo-seed.html">HO Demo Seed</a>).</li><li><strong>Production</strong>, at <code>https://app.getvera.site</code>, follows the <code>production</code> branch. Only the <strong>Promote</strong> workflow moves that branch.</li></ul><p>So a merge reaches production in two steps: merge, which deploys to staging, then promote.</p><div class="warning custom-block"><p class="custom-block-title">Until Phase 3 of issue 2523</p><p>Until the production Railway service is pointed at the <code>production</code> branch, production still follows <code>main</code> and every merge deploys there too. This page describes the setup after that switch.</p></div><h2 id="promote" tabindex="-1">Promote <a class="header-anchor" href="#promote" aria-label="Permalink to &quot;Promote&quot;">​</a></h2><ol><li>Merge the pull request to <code>main</code> and wait for CI on <code>main</code> to finish (<code>test</code> and <code>smoke</code>, about three minutes).</li><li>Check that staging is running the merge: <code>curl -s https://vera-staging-staging-7e23.up.railway.app/version</code> should show the merge commit.</li><li>If the change is visible on a page, look at it on staging.</li><li>On GitHub, open <strong>Actions → Promote → Run workflow</strong>. Leave <strong>commit</strong> blank to promote the head of <code>main</code>, or paste a commit. Run it.</li></ol><p>Promote moves <code>production</code> to that commit, and Railway deploys it. Promote refuses, with the reason in the run&#39;s log and summary, when:</p><ul><li>CI on the commit is still running, or any check failed, or <code>test</code> or <code>smoke</code> did not pass;</li><li>staging is down, or is not yet running that commit or a later one;</li><li>the move is not a fast-forward of <code>production</code> (see Roll back);</li><li>anyone other than the repository owner runs it.</li></ul><p>Promote runs no tests of its own. It reads the results CI already recorded on the commit, so it costs well under a minute.</p><h2 id="roll-back" tabindex="-1">Roll back <a class="header-anchor" href="#roll-back" aria-label="Permalink to &quot;Roll back&quot;">​</a></h2><p>Run <strong>Promote</strong> with <strong>commit</strong> set to the earlier commit and <strong>rollback</strong> ticked. A rollback must name a commit production already contains, and it is the only time Promote moves <code>production</code> backwards. The next normal promotion moves it forward again.</p><p>Rolling back code does not roll back migrations. A migration already applied to production stays applied, so a rollback is safe only when the earlier code works with the newer schema. VERA&#39;s migrations add columns and tables rather than remove them, which is what keeps this true.</p><h2 id="check-what-production-is-running" tabindex="-1">Check what production is running <a class="header-anchor" href="#check-what-production-is-running" aria-label="Permalink to &quot;Check what production is running&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://app.getvera.site/version</span></span></code></pre></div><p><code>commit</code> is the full commit Railway deployed. Compare it with the commit you promoted. If <code>started_at</code> is earlier than the promotion, Railway has not finished deploying yet.</p>',16)])])}const g=o(s,[["render",n]]);export{m as __pageData,g as default};
